import{_ as d,a0 as p,w as r,s as c,I as i,x as o,a1 as l,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"使用 GTWS 管理複雜的 Git 工作空間 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GTWS 管理複雜的 Git 工作空間 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GTWS 管理複雜的 Git 工作空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GTWS 管理複雜的 Git 工作空間 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces","title":"使用 GTWS 管理複雜的 Git 工作空間","tag":"202004","desc":""},"relativePath":"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces.md","filePath":"[post].md"}'),n={name:"202004/20200213 Manage complex Git workspaces with Great Teeming Workspaces.md"};function g(u,e,m,T,h,b){const t=p("Link");return r(),c("div",null,[e[20]||(e[20]=i("h1",{id:"使用-gtws-管理複雜的-git-工作空間",tabindex:"-1"},[o("使用 GTWS 管理複雜的 Git 工作空間 "),i("a",{class:"header-anchor",href:"#使用-gtws-管理複雜的-git-工作空間","aria-label":"Permalink to “使用 GTWS 管理複雜的 Git 工作空間”"},"​")],-1)),e[21]||(e[21]=i("blockquote",null,[i("p",null,"GTWS 是一系列腳本，它使我們在開發環境中管理不同的項目和項目的各個版本變得很容易。")],-1)),e[22]||(e[22]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/27/182149xh9s7kb5bkf5875b.jpg",alt:""})],-1)),i("p",null,[l(t,{href:"https://github.com/dang/gtws"},{default:s(()=>[...e[0]||(e[0]=[o("Great Teeming Workspaces",-1)])]),_:1}),e[1]||(e[1]=o("（GTWS）是一個 Git 的複雜工作空間管理工具包，它使我們在開發環境中管理不同的項目和項目的各個版本變得很容易。",-1))]),i("p",null,[e[3]||(e[3]=o("有點像 Python 的 ",-1)),l(t,{href:"https://docs.python.org/3/library/venv.html"},{default:s(()=>[...e[2]||(e[2]=[o("venv",-1)])]),_:1}),e[4]||(e[4]=o("，但不是為 Python 語言準備的。GTWS 用來管理多個項目的多個版本的工作空間。你可以很容易地創建、更新、進入和離開工作空間，每個項目或版本的組合（最多）有一個本地的 origin，用來與 upstream 同步 — 其餘的所有工作空間都從本地的 origin 更新。",-1))]),e[23]||(e[23]=a('<h3 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to “部署”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>${GTWS_ORIGIN}/&lt;project&gt;/&lt;repo&gt;[/&lt;version&gt;]</span></span>\n<span class="line"><span>${GTWS_BASE_SRCDIR}/&lt;project&gt;/&lt;version&gt;/&lt;workspacename&gt;/{&lt;repo&gt;[,&lt;repo&gt;...]}</span></span></code></pre></div><p>源代碼目錄的每一級（包括全局的家目錄）可以包含一個 <code>.gtwsrc</code> 文件，這個文件中維護與當前級相關的設置和 bash 代碼。每一級的配置會覆蓋上一級。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>用下面的命令檢出 GTWS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/dang/gtws.git</span></span></code></pre></div><p>配置你的 <code>${HOME}/.gtwsrc</code>。它應該包含 <code>GTWS_ORIGIN</code>，也可以再包含 <code>GTWS_SETPROMPT</code>。</p><p>把倉庫目錄加到環境變量中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export PATH=&quot;${PATH}:/path/to/gtws</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>通過級聯 <code>.gtwsrc</code> 文件來進行配置。它從根目錄向下遍歷，會執行在每級目錄中找到的 <code>.gtwsrc</code> 文件。下級目錄的文件會覆蓋上一級。</p><p>在你最上層的文件 <code>~/.gtws/.gtwsrc</code> 中進行如下設置：</p><ul><li><code>GTWS_BASE_SRCDIR</code>：所有項目源文件目錄樹的基目錄。默認為 <code>$HOME/src</code>。</li><li><code>GTWS_ORIGIN</code>： 指定 origin git 目錄樹的路徑。默認為 <code>$HOME/origin</code>。</li><li><code>GTWS_SETPROMPT</code>： 可選配置。如果配置了這個參數，shell 提示符會有工作空間的名字。</li><li><code>GTWS_DEFAULT_PROJECT</code>： 不指定項目或項目未知時默認的項目名。如果不指定，使用命令列時必須指明項目。</li><li><code>GTWS_DEFAULT_PROJECT_VERSION</code>： 檢出的默認版本。默認為 <code>master</code>。</li></ul><p>在每個項目的根目錄進行以下設置：</p><ul><li><code>GTWS_PROJECT</code>： 項目的名字（和基目錄）。</li><li><code>gtws_project_clone</code>： 這個函數用於克隆一個項目的指定版本。如果未定義，它會假定項目的 origin 對每一個版本都有一個單獨的目錄，這樣會導致克隆一堆 Git 倉庫。</li><li><code>gtws_project_setup</code>： 在克隆完所有的倉庫後，可以選擇是否調用這個函數，調用後可以對項目進行必要的配置，如在 IDE 中配置工作空間。</li></ul><p>在項目版本級進行以下設置：</p><ul><li><code>GTWS_PROJECT_VERSION：</code> 項目的版本。用於正確地從 origin 拉取代碼。類似 Git 中的分支名字。</li></ul><p>下面這些參數可以在目錄樹的任意地方進行配置，如果能生效，它們可以被重寫多次：</p><ul><li><code>GTWS_PATH_EXTRA</code>： 這些是工作空間中加到路徑後的額外的路徑元素。</li><li><code>GTWS_FILES_EXTRA</code>： 這些是不在版本控制內，但應該在工作空間中被檢出的額外的文件。這些文件包括 <code>.git/info/exclude</code>，每個文件都與倉庫的基目錄相關聯。</li></ul><h3 id="origin-目錄" tabindex="-1">origin 目錄 <a class="header-anchor" href="#origin-目錄" aria-label="Permalink to “origin 目錄”">​</a></h3><p><code>GTWS_ORIGIN</code> （大部分腳本中）指向拉取和推送的原始 Git 檢出目錄。</p><p><code>${GTWS_ORIGIN}</code> 部署：</p><ul><li><code>/&lt;project&gt;</code><ul><li>這是一個項目的倉庫的基目錄。</li><li>如果指定了 <code>gtws_project_clone</code>，你可以配置任意的部署路徑。</li><li>如果沒有指定 <code>gtws_project_clone</code>，這個路徑下必須有個名為 <code>git</code> 的子目錄，且 <code>git</code> 目錄下有一系列用來克隆的裸 Git 倉庫。</li></ul></li></ul><h3 id="工作流示例" tabindex="-1">工作流示例 <a class="header-anchor" href="#工作流示例" aria-label="Permalink to “工作流示例”">​</a></h3><p>假設你有一個項目名為 <code>Foo</code>，它的 upstream 為 <code>github.com/foo/foo.git</code>。這個倉庫有個名為 <code>bar</code> 的子模組，它的 upstream 是 <code>github.com/bar/bar.git</code>。Foo 項目在 master 分支開發，使用穩定版本的分支。</p><p>為了能在 Foo 中使用 GTWS，你首先要配置目錄結構。本例中假設你使用默認的目錄結構。</p><ul><li>配置你最上層的 <code>.gtwsrc</code>： <ul><li><code>cp ${GTWS_LOC}/examples/gtwsrc.top ~/.gtwsrc</code></li><li>根據需要修改 <code>~/.gtwsrc</code>。</li></ul></li><li>創建頂級目錄： <ul><li><code>mkdir -p ~/origin ~/src</code></li></ul></li><li>創建並配置項目目錄： <ul><li><p><code>mkdir -p ~/src/foo</code></p><p><code>cp ${GTWS_LOC}/examples/gtwsrc.project ~/src/foo/.gtwsrc</code></p></li><li><p>根據需要修改 <code>~/src/foo/.gtwsrc</code>。</p></li></ul></li><li>創建並配置 master 版本目錄： <ul><li><p><code>mkdir -p ~/src/foo/master</code></p><p><code>cp ${GTWS_LOC}/examples/gtwsrc.version ~/src/foo/master/.gtwsrc</code></p></li><li><p>根據需要修改 <code>~/src/foo/master/.gtwsrc</code>。</p></li></ul></li><li>進入版本目錄並創建一個臨時工作空間來配置鏡像： <ul><li><p><code>mkdir -p ~/src/foo/master/tmp</code></p><p><code>cd ~/src/foo/master/tmp</code></p><p><code>git clone --recurse-submodules git://github.com/foo/foo.git</code></p><p><code>cd foo</code></p><p><code>gtws-mirror -o ~/origin -p foo</code>（譯註：這個地方原文有誤，不加 <code>-s</code> 參數會報錯）</p></li><li><p>上面命令會創建 <code>~/origin/foo/git/foo.git</code> 和 <code>~/origin/foo/submodule/bar.git</code>。</p></li><li><p>以後的克隆操作會從這些 origin 而不是 upstream 克隆。</p></li><li><p>現在可以刪除工作空間了。</p></li></ul></li></ul><p>到現在為止，Foo 的 master 分支的工作可以結束了。假設你現在想修復一個 bug，名為 <code>bug1234</code>。你可以脱離你當前的工作空間為修復這個 bug 單獨創建一個工作空間，之後在新創建的工作空間中開發。</p><ul><li>進入版本目錄，創建一個新的工作空間： <ul><li><p><code>cd ~/src/foo/master</code></p><p><code>mkws bug1234</code></p></li><li><p>上面的命令創建了 <code>bug1234/</code>，在這個目錄下檢出了 Foo（和它的子模組 <code>bar</code>），並創建了 <code>build/foo</code> 來構建它。</p></li></ul></li><li>有兩種方式進入工作空間： <ul><li><p><code>cd ~/src/foo/master/bug1234</code></p><p><code>startws</code></p><p>或者</p><p><code>cd ~/src/foo/master/</code></p><p><code>startws bug1234</code></p></li><li><p>上面的命令在 <code>bug1234</code> 工作空間中開啓了一個子 shell。這個 shell 有 GTWS 的環境和你在各級 <code>.gtwsrc</code> 文件中設置的環境。它也把你工作空間的基目錄加入到了 CD，因此你可以從 base 路徑 <code>cd</code> 到相關的目錄中。</p></li><li><p>現在你可以修復 <code>bug1234</code> 了，構建、測試、提交你的修改。當你可以把代碼推送到 upstream 時，執行下面的命令：</p><p><code>cd foo</code></p><p><code>wspush</code></p></li><li><p><code>wspush</code> 會把代碼推送到與你工作空間相關的分支 — 先推送到本地的 origin，再推送到 upstream。</p></li><li><p>當 upstream 有修改時，你可以用下面的命令同步到本地：</p><p><code>git sync</code></p></li><li><p>上面的命令調用了 GTWS 的 <code>git-sync</code> 腳本，會從本地 origin 更新代碼。使用下面的命令來更新本地的 origin：</p><p><code>git sync -o</code></p></li><li><p>上面的命令會更新你本地的 origin 和子模組的鏡像，然後用那些命令來更新你的檢出倉庫的代碼。<code>git-sync</code> 也有一些其他的很好的工鞥。</p></li><li><p>當要結束工作空間中的工作時，直接退出 shell：</p><p><code>exit</code></p></li><li><p>你可以在任何時間重複進入工作空間，也可以在同一時間在相同的工作空間中開多個 shell。</p></li></ul></li><li>當你不需要某個工作空間時，你可以使用 <code>rmws</code> 來刪除它，或者直接刪除它的目錄樹。</li><li>還有一個腳本 <code>tmws</code> 使用 tmux 進入工作空間，能創建一系列的窗口/窗格，這完美契合我的工作流。你可以根據你自己的需求來修改它。</li></ul><hr>',30)),i("p",null,[e[6]||(e[6]=o("via: ",-1)),l(t,{href:"https://opensource.com/article/20/2/git-great-teeming-workspaces"},{default:s(()=>[...e[5]||(e[5]=[o("https://opensource.com/article/20/2/git-great-teeming-workspaces",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=o("作者：",-1)),l(t,{href:"https://opensource.com/users/dang"},{default:s(()=>[...e[7]||(e[7]=[o("Daniel Gryniewicz",-1)])]),_:1}),e[12]||(e[12]=o(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[8]||(e[8]=[o("lujun9972",-1)])]),_:1}),e[13]||(e[13]=o(" 譯者：",-1)),l(t,{href:"https://github.com/lxbwolf"},{default:s(()=>[...e[9]||(e[9]=[o("lxbwolf",-1)])]),_:1}),e[14]||(e[14]=o(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[10]||(e[10]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[17]||(e[17]=o("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[o("LCTT",-1)])]),_:1}),e[18]||(e[18]=o(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[o("Linux中國",-1)])]),_:1}),e[19]||(e[19]=o(" 榮譽推出",-1))])])}const w=d(n,[["render",g]]);export{k as __pageData,w as default};
